WHERE ProductID = 1;

-- Generate manufacturing documentation example
SELECT GenerateManufacturingDocumentation(1);

-- Delete a product
DELETE FROM Products
WHERE ProductID = 1;

-- This script shows how to create, retrieve, update, delete, and generate documentation for screwdriver products.

#end of the script
```

